  .glu-ov-body { padding: 16px; } .glu-ov button { min-width: 0; flex: 1; } .glu-ov button.gsel-box { flex: none; }
  .glu-ov .numctl { grid-template-columns: minmax(0, 1fr); gap: 8px; } .glu-ov .stepper { justify-self: start; }
